import{_ as t,o as d,c as o,ae as a}from"./chunks/framework.DQC_QtFV.js";const p=JSON.parse('{"title":"环境变量（.env）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/env.md","filePath":"guide/env.md","lastUpdated":1793162416000}'),c={name:"guide/env.md"};function r(h,e,n,l,i,s){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="环境变量-env" tabindex="-1">环境变量（.env） <a class="header-anchor" href="#环境变量-env" aria-label="Permalink to &quot;环境变量（.env）&quot;">​</a></h1><p><code>.env</code> 是 <code>compose.yaml</code> 旁边的一个纯 env 文件：<code>KEY=value</code> 行和 <code>#</code> 注释，没有别的。 复制 <code>.env.example</code> 改成 <code>.env</code> 再填。下面是全部变量。</p><h2 id="必须填" tabindex="-1">必须填 <a class="header-anchor" href="#必须填" aria-label="Permalink to &quot;必须填&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>含义</th></tr></thead><tbody><tr><td><code>CONSOLE_PASSWORD</code></td><td>面板密码。它是面板前面唯一的一道门，请设长一点</td></tr><tr><td><code>DRIVER_TOKEN</code></td><td>内部令牌之一，驱动程序没有它拒绝启动；控制台和机器人用它调驱动程序</td></tr><tr><td><code>BOT_TOKEN</code></td><td>内部令牌之一，控制台持有它，永远不下发给浏览器</td></tr><tr><td><code>SANDBOX_EXEC_TOKEN</code></td><td>内部令牌之一，机器人用它调沙箱；沙箱里只有 root 能读到它</td></tr></tbody></table><p>三个令牌用 <code>openssl rand -hex 32</code> 生成。它们不离开这套栈：每个服务只拿到自己需要的那些。</p><h2 id="qq-来源-二选一" tabindex="-1">QQ 来源：二选一 <a class="header-anchor" href="#qq-来源-二选一" aria-label="Permalink to &quot;QQ 来源：二选一&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>含义</th></tr></thead><tbody><tr><td><code>QQ_DEB_URL</code></td><td><code>qq</code> 容器下载固定版本的地址。留空并改成挂载 deb，就走文件来源</td></tr></tbody></table><p>两个都给了，容器会拒绝启动并说明；都没给也一样。细节见 <a href="./first-start.html">首次启动</a>。</p><h2 id="可选" tabindex="-1">可选 <a class="header-anchor" href="#可选" aria-label="Permalink to &quot;可选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>默认</th><th>含义</th></tr></thead><tbody><tr><td><code>PI_OFFLINE</code></td><td><code>0</code></td><td><code>1</code> 关闭 pi 拉取模型目录，用于完全离线的运行</td></tr><tr><td><code>KEYX_TIMEOUT_S</code></td><td><code>900</code></td><td>首次启动等数据库密钥提取多久。实测提取最多约 8 分钟，机器慢就调大；超时不致命，驱动程序会继续等</td></tr><tr><td><code>PERSONAL_BOT_TAG</code></td><td>空（<code>latest</code>）</td><td>要运行的镜像 tag。留空用最新发布；设为 <code>v2026.1025.0</code> 这样的 tag 即固定版本</td></tr></tbody></table><h2 id="模型自己的设置不在环境变量里" tabindex="-1">模型自己的设置不在环境变量里 <a class="header-anchor" href="#模型自己的设置不在环境变量里" aria-label="Permalink to &quot;模型自己的设置不在环境变量里&quot;">​</a></h2><p>用哪个模型、谁可以跟它说话、它能记住什么、它的命令可以访问哪些域名、消息怎么合并、 排队怎么排——全都在 <a href="./console/">控制台</a>里，改完即生效，不需要动 <code>.env</code>，也不需要重建容器。</p><p><code>compose.yaml</code> 里还有两个屏幕相关的变量（<code>SCREEN_W</code>、<code>SCREEN_H</code>，默认 1280x800）， 它们决定实时画面的大小；改它们要同时改 <code>compose.yaml</code> 并重建 qq 镜像。</p>',13)])])}const b=t(c,[["render",r]]);export{p as __pageData,b as default};
